function createSession(identity) {
  return { username: identity.username, expiresAt: Date.now() + 3600000 };
}

login(credentials) {
    const identity = validateCredentials(credentials);
    const session = createSession(identity);
    this.savedSession = session;
    return session;
  }

function validateCredentials(credentials) {
  if (!credentials?.username || !credentials?.token) {
    throw new Error("Missing authentication credentials");
  }
  return { username: credentials.username, token: credentials.token };
}

restore() {
    if (!this.savedSession || this.savedSession.expiresAt <= Date.now()) return null;
    return this.savedSession;
  }

handle(rawInput, context) {
    const command = normalizeInput(rawInput);
    return this.handleRequest(command, context);
  }

function normalizeInput(rawInput) {
  if (typeof rawInput !== "string") throw new TypeError("Expected spoken text");
  return rawInput.trim().toLowerCase().replace(/\s+/g, " ");
}

